function Modal({title,children,close}){const ref=useRef();useEffect(()=>{const old=document.activeElement;ref.current?.focus();const key=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const a=[...ref.current.querySelectorAll('button,input,select,textarea,[href],summary')].filter(x=>!x.disabled);if(!a.length)return;if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0].focus();}}};document.addEventListener('keydown',key);return()=>{document.removeEventListener('keydown',key);old?.focus();};},[]);return <div className="modal-backdrop"><section className="modal" role="dialog" aria-modal="true" aria-label={title} ref={ref} tabIndex={-1}><div className="modal-head"><h2>{title}</h2><button className="icon-btn" aria-label="Close evidence" onClick={close}><X size={20}/></button></div>{children}</section></div>}
